export function getCopy(locale: string, dictionary: Record<string, string> = {}): UiCopy {
  const manual = translations[locale] || {};
  const localized = (value: string, fallback?: string) => dictionary[value] || fallback || value;
  return {
    nav: english.nav.map((value, index) => localized(value, manual.nav?.[index])),
    kicker: localized(english.kicker, manual.kicker),
    title: localized(english.title, manual.title),
    description: localized(english.description, manual.description),
    search: localized(english.search, manual.search),
    searchButton: localized(english.searchButton, manual.searchButton),
    evidence: localized(english.evidence, manual.evidence),
    products: localized(english.products, manual.products),
    productsDescription: localized(english.productsDescription, manual.productsDescription).replace(/12/g, "13"),
    guides: localized(english.guides, manual.guides),
    categories: localized(english.categories, manual.categories),
    sources: localized(english.sources, manual.sources),
    independent: localized(english.independent, manual.independent),
  };
}

